def token_span(old_ids: list[int], new_ids: list[int]) -> Span:
    """Token-level edit span (snapped out from the byte delta to token boundaries)."""
    p = 0
    while p < len(old_ids) and p < len(new_ids) and old_ids[p] == new_ids[p]:
        p += 1
    s = 0
